public int maxSubarraySumCircular(int[] nums) {
    int n = nums.length;
    int best = Integer.MIN_VALUE;
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int k = 0; k < n; k++) {
            sum += nums[(i + k) % n];
            best = Math.max(best, sum);
        }
    }
    return best;
}

